WITH valid AS (SELECT *, CASE WHEN discount_pct >= 0.34 THEN 'High' WHEN discount_pct >= 0.15 THEN 'Medium' ELSE 'Low' END AS discount_pct_band, COALESCE(channel, 'UNKNOWN') AS channel_clean FROM promotions WHERE discount_pct BETWEEN 0.25 AND 0.32 AND ends_on > DATE '2023-07-12') SELECT id, promo_code FROM valid EXCEPT SELECT id, promo_code FROM promotions WHERE discount_pct BETWEEN 0.24 AND 0.3
